  const unresolvedFlags=['axis','classification','layer','archive'];function profileEnabled(){return document.getElementById('namingProfile').value==='jnp'}function displayedSystemName(s){return profileEnabled()?s.name:''}function reviewKey(s){return s.group+','+s.number}function reviewFor(s){const key=reviewKey(s),record=model.reviews[key]||{flags:[],note:'',customName:''};return pendingSpriteNames.has(key)?{...record,customName:pendingSpriteNames.get(key)}:record}function reviewMatches(s,filter){const r=reviewFor(s),flags=r.flags||[];if(filter==='all')return true;if(filter==='unresolved')return unresolvedFlags.some(flag=>flags.includes(flag));if(filter==='unreviewed')return !flags.length&&!r.note&&!r.customName;return flags.includes(filter)}function reviewBadges(s){const flags=reviewFor(s).flags||[];return (flags.includes('favorite')?'★':'')+(flags.includes('approved')?'✓':'')+(unresolvedFlags.some(flag=>flags.includes(flag))?'⚑':'')}
  function renderPaletteChoices(){const select=document.getElementById('paletteSelect'),before=select.value,mode=paletteSort.value;select.textContent='';const items=model.palettes.slice();if(mode==='number')items.sort((a,b)=>a.group-b.group||a.number-b.number);else if(mode==='name')items.sort((a,b)=>(a.role||'').localeCompare(b.role||'',undefined,{numeric:true,sensitivity:'base'})||a.group-b.group||a.number-b.number);else if(mode==='category')items.sort((a,b)=>a.category.localeCompare(b.category)||a.group-b.group||a.number-b.number);else items.sort((a,b)=>a.index-b.index);let last='';for(const palette of items){if(mode==='category'&&palette.category!==last){const heading=document.createElement('option');heading.disabled=true;heading.textContent='── '+palette.category+' ──';select.append(heading);last=palette.category}const option=document.createElement('option'),temporary=palette.temporaryLifecycle?' · Temporary '+palette.temporaryLifecycle.lifecycleId+' · '+palette.temporaryLifecycle.ownerCount+' owner(s)'+(palette.temporaryLifecycle.stale?' · STALE':''):'';option.value=palette.index;option.title=palette.identityDetail||'';option.textContent=(palette.identityLabel||(palette.group+','+palette.number))+' · '+palette.role+' · '+palette.spriteCount+' sprite(s)'+(palette.link!==null?' · linked to '+palette.link:'')+temporary;select.append(option)}if([...select.options].some(x=>x.value===before))select.value=before;if(!model.palettes.length){const option=document.createElement('option');option.textContent='No embedded palettes';select.append(option);select.disabled=true;for(const id of ['applyPalettePreview','compareAct','replacePalette','previewReversedPalette','saveReversedPalette','exportAct'])document.getElementById(id).disabled=true}document.getElementById('previewReversedPalette').onclick=()=>vscode.postMessage({type:'previewReversedPalette',paletteIndex:Number(select.value)});document.getElementById('saveReversedPalette').onclick=()=>vscode.postMessage({type:'saveReversedPalette',paletteIndex:Number(select.value)})}
