  function setZoom(value){zoomScale=Math.max(.001,Math.min(8,Number.isFinite(value)?value:1));document.getElementById('zoom').value=Math.round(zoomScale*100);document.getElementById('zoomValue').textContent=Math.round(zoomScale*100)+'%';redraw();saveViewState()}
