    lines.push(`| ${sprite.group},${sprite.number} | ${sprite.width}×${sprite.height} | ${sprite.axisX},${sprite.axisY} | ${sprite.format} | ${sprite.colorDepth}-bit | ${sprite.paletteIndex} | ${sprite.dataSize === 0 ? sprite.link : '—'} | ${refs.length} |`);
